  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold ${ASSIGNMENT_STYLES[status]}`}>
      {assignmentStatusLabel(status)}
    </span>
  );
}

